    foreach($studies as $study){$ids=$wpdb->get_col($wpdb->prepare('SELECT id FROM '.$wpdb->prefix.'eipsi_engine_study_executions WHERE study_id=%s',$study));foreach($ids as $execution)foreach(array('block_executions','execution_events','random_decisions','execution_commands','withdrawal_records','notification_intents','submission_journal') as $table)$wpdb->delete($wpdb->prefix.'eipsi_engine_'.$table,array('execution_id'=>$execution));foreach(array('anonymous_access','participants','enrollment_receipts','study_executions','public_studies','study_versions') as $table)$wpdb->delete($wpdb->prefix.'eipsi_engine_'.$table,array('study_id'=>$study));}
    foreach(array_unique($posts) as $post)wp_delete_post($post,true);foreach($options as $key=>$value){if($value===false)delete_option($key);else update_option($key,$value);}wp_set_current_user(1);
}
echo 'H metrics '.C\Canonical::json($metrics)."\n";echo $tests.' tests, '.$failures." failures\n";exit($failures?1:0);
